#include <iostream>
#include <string>

int main() {
    std::string s;
    std::getline(std::cin, s);

    // Replace first occurrence of "at" with "@"
    size_t pos = s.find("at");
    if (pos != std::string::npos) {
        s.replace(pos, 2, "@");
    }

    // If the first character is '@', prepend "at" and replace next "at" with "@"
    if (!s.empty() && s[0] == '@') {
        s = "at" + s.substr(1);
        size_t second_at_pos = s.find("at", 2);
        if (second_at_pos != std::string::npos) {
            s.replace(second_at_pos, 2, "@");
        }
    }

    // If "dot" exists in s
    if (s.find("dot") != std::string::npos) {
        // Replace all "dot" with "."
        size_t start_pos = 0;
        while ((start_pos = s.find("dot", start_pos)) != std::string::npos) {
            s.replace(start_pos, 3, ".");
            start_pos += 1; // move forward to avoid infinite loop
        }

        // If s starts with '.', replace it with "dot"
        if (!s.empty() && s[0] == '.') {
            s.replace(0, 1, "dot");
        }

        // If s ends with '.', replace it with "dot"
        if (!s.empty() && s.back() == '.') {
            s.replace(s.size() - 1, 1, "dot");
        }
    }

    std::cout << s << std::endl;
    return 0;
}

